use std::fs
use std::collections::HashMap

fn before(a: (string, int), b: (string, int)) -> bool {
    if a.1 != b.1 {
        return a.1 > b.1
    }
    a.0 < b.0
}

fn add(counts: HashMap<string, int>, w: string) {
    if counts.contains_key(w) {
        let n: int = counts[w]
        counts.insert(w, n + 1)
    } else {
        counts.insert(w, 1)
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut k: int = 0
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            k = line.trim().parse::<int>().unwrap_or(0)
            continue
        }
        let mut cur = ""
        for c in line.chars() {
            if c.is_ascii_alphanumeric() {
                cur = cur + c.to_ascii_lowercase().to_string()
            } else {
                if cur.len() > 0 {
                    add(counts, cur)
                    cur = ""
                }
            }
        }
        if cur.len() > 0 {
            add(counts, cur)
        }
    }
    let mut items: Vec<(string, int)> = []
    for key in counts.keys() {
        items.push((key, counts[key]))
    }
    let n: int = items.len() as int
    let mut i: int = 1
    while i < n {
        let mut j = i
        while j > 0 && before(items[j as usize], items[(j - 1) as usize]) {
            let t = items[j as usize]
            items[j as usize] = items[(j - 1) as usize]
            items[(j - 1) as usize] = t
            j -= 1
        }
        i += 1
    }
    let mut p: int = 0
    for it in items {
        if p >= k { break }
        println("${it.0} ${it.1}")
        p += 1
    }
}

